response.content:
{
  "semantic_models": [
    {
      "name": "member_dim",
      "model": "ref('members')",
      "defaults": {
        "agg_time_dimension": "registered_at"
      },
      "entities": [
        {
          "name": "member",
          "type": "primary",
          "expr": "member_id"
        },
        {
          "name": "home_store",
          "type": "foreign",
          "expr": "home_store_id"
        }
      ],
      "dimensions": [
        {
          "name": "registered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        },
        {
          "name": "tier",
          "type": "categorical"
        }
      ],
      "measures": [
        {
          "name": "new_member_count_measure",
          "expr": "member_id",
          "agg": "count"
        }
      ]
    },
    {
      "name": "store_dim",
      "model": "ref('stores')",
      "entities": [
        {
          "name": "store",
          "type": "primary",
          "expr": "store_id"
        }
      ],
      "dimensions": [
        {
          "name": "region",
          "type": "categorical"
        },
        {
          "name": "store_name",
          "type": "categorical"
        }
      ]
    },
    {
      "name": "home_store_dim",
      "model": "ref('stores')",
      "entities": [
        {
          "name": "home_store",
          "type": "primary",
          "expr": "store_id"
        }
      ],
      "dimensions": [
        {
          "name": "region",
          "type": "categorical"
        },
        {
          "name": "store_name",
          "type": "categorical"
        }
      ]
    },
    {
      "name": "order_facts",
      "model": "ref('order_facts')",
      "defaults": {
        "agg_time_dimension": "ordered_at"
      },
      "entities": [
        {
          "name": "order",
          "type": "primary",
          "expr": "order_id"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        },
        {
          "name": "store",
          "type": "foreign",
          "expr": "store_id"
        },
        {
          "name": "home_store",
          "type": "foreign",
          "expr": "home_store_id"
        }
      ],
      "dimensions": [
        {
          "name": "ordered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        },
        {
          "name": "channel",
          "type": "categorical"
        },
        {
          "name": "status",
          "type": "categorical"
        }
      ],
      "measures": [
        {
          "name": "order_count_measure",
          "expr": "order_id",
          "agg": "count"
        },
        {
          "name": "paid_order_count_measure",
          "expr": "CASE WHEN status = 'paid' THEN order_id END",
          "agg": "count"
        },
        {
          "name": "valid_order_count_measure",
          "expr": "CASE WHEN status = 'paid' AND paid_cents - refund_cents > 0 THEN order_id END",
          "agg": "count"
        },
        {
          "name": "cancelled_order_count_measure",
          "expr": "CASE WHEN status = 'cancelled' THEN order_id END",
          "agg": "count"
        },
        {
          "name": "refund_order_count_measure",
          "expr": "CASE WHEN status = 'paid' AND refund_cents > 0 THEN order_id END",
          "agg": "count"
        },
        {
          "name": "partial_refund_order_count_measure",
          "expr": "CASE WHEN status = 'paid' AND refund_cents > 0 AND refund_cents < paid_cents THEN order_id END",
          "agg": "count"
        },
        {
          "name": "full_refund_order_count_measure",
          "expr": "CASE WHEN status = 'paid' AND paid_cents > 0 AND refund_cents = paid_cents THEN order_id END",
          "agg": "count"
        },
        {
          "name": "payment_cents_measure",
          "expr": "CASE WHEN status = 'paid' THEN paid_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "refund_cents_measure",
          "expr": "CASE WHEN status = 'paid' THEN refund_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "net_sales_cents_measure",
          "expr": "CASE WHEN status = 'paid' THEN paid_cents - refund_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "gross_cents_measure",
          "expr": "CASE WHEN status = 'paid' THEN gross_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "discount_cents_measure",
          "expr": "CASE WHEN status = 'paid' THEN gross_cents - paid_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "buyer_count_measure",
          "expr": "CASE WHEN status = 'paid' AND paid_cents - refund_cents > 0 THEN member_id END",
          "agg": "count_distinct"
        },
        {
          "name": "refund_buyer_count_measure",
          "expr": "CASE WHEN status = 'paid' AND refund_cents > 0 THEN member_id END",
          "agg": "count_distinct"
        },
        {
          "name": "selling_store_count_measure",
          "expr": "CASE WHEN status = 'paid' AND paid_cents - refund_cents > 0 THEN store_id END",
          "agg": "count_distinct"
        },
        {
          "name": "valid_order_items_measure",
          "expr": "CASE WHEN status = 'paid' AND paid_cents - refund_cents > 0 THEN quantity ELSE 0 END",
          "agg": "sum"
        }
      ]
    },
    {
      "name": "member_order_history",
      "model": "ref('member_order_history')",
      "defaults": {
        "agg_time_dimension": "ordered_at"
      },
      "entities": [
        {
          "name": "valid_order",
          "type": "primary",
          "expr": "order_id"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        }
      ],
      "dimensions": [
        {
          "name": "ordered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        }
      ],
      "measures": [
        {
          "name": "first_buyer_count_measure",
          "expr": "CASE WHEN valid_order_seq = 1 THEN member_id END",
          "agg": "count_distinct"
        },
        {
          "name": "first_order_sales_cents_measure",
          "expr": "CASE WHEN valid_order_seq = 1 THEN net_sales_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "first_order_count_measure",
          "expr": "CASE WHEN valid_order_seq = 1 THEN order_id END",
          "agg": "count"
        },
        {
          "name": "repeat_order_count_measure",
          "expr": "CASE WHEN valid_order_seq >= 2 THEN order_id END",
          "agg": "count"
        }
      ]
    },
    {
      "name": "monthly_member_activity",
      "model": "ref('monthly_member_activity')",
      "defaults": {
        "agg_time_dimension": "activity_month"
      },
      "entities": [
        {
          "name": "member_month",
          "type": "primary",
          "expr": "member_month_key"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        }
      ],
      "dimensions": [
        {
          "name": "activity_month",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        }
      ],
      "measures": [
        {
          "name": "monthly_buyer_count_measure",
          "expr": "CASE WHEN valid_order_count >= 1 THEN 1 ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "monthly_repeat_buyer_count_measure",
          "expr": "CASE WHEN valid_order_count >= 2 THEN 1 ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "monthly_paid_buyer_count_measure",
          "expr": "CASE WHEN paid_qualified = 1 THEN 1 ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "monthly_paid_order_count_measure",
          "expr": "CASE WHEN paid_qualified = 1 THEN valid_order_count ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "monthly_paid_sales_cents_measure",
          "expr": "CASE WHEN paid_qualified = 1 THEN net_sales_cents ELSE 0 END",
          "agg": "sum"
        },
        {
          "name": "monthly_paid_repeat_buyer_count_measure",
          "expr": "CASE WHEN paid_qualified = 1 AND valid_order_count >= 2 THEN 1 ELSE 0 END",
          "agg": "sum"
        }
      ]
    }
  ],
  "metrics": [
    {
      "name": "order_count",
      "label": "创建订单数",
      "description": "按下单日期统计全部订单，每个订单号一次，包含取消单。",
      "type": "simple",
      "type_params": {
        "measure": "order_count_measure"
      }
    },
    {
      "name": "paid_order_count",
      "label": "支付订单数",
      "description": "状态为 paid 的订单数，包括后来全部退款的订单。",
      "type": "simple",
      "type_params": {
        "measure": "paid_order_count_measure"
      }
    },
    {
      "name": "valid_order_count",
      "label": "有效订单数",
      "description": "状态为 paid 且实付金额减退款金额大于零的订单数；取消和全退不计。",
      "type": "simple",
      "type_params": {
        "measure": "valid_order_count_measure"
      }
    },
    {
      "name": "cancelled_order_count",
      "label": "取消订单数",
      "description": "状态为 cancelled 的订单数。",
      "type": "simple",
      "type_params": {
        "measure": "cancelled_order_count_measure"
      }
    },
    {
      "name": "refund_order_count",
      "label": "退款订单数",
      "description": "paid 状态且退款金额大于零的订单数，包括部分退款与全部退款。",
      "type": "simple",
      "type_params": {
        "measure": "refund_order_count_measure"
      }
    },
    {
      "name": "partial_refund_order_count",
      "label": "部分退款订单数",
      "description": "paid 状态且退款大于零、小于实付金额的订单数。",
      "type": "simple",
      "type_params": {
        "measure": "partial_refund_order_count_measure"
      }
    },
    {
      "name": "full_refund_order_count",
      "label": "全额退款订单数",
      "description": "paid 状态且实付大于零、退款等于实付的订单数。",
      "type": "simple",
      "type_params": {
        "measure": "full_refund_order_count_measure"
      }
    },
    {
      "name": "payment_cents",
      "label": "实付金额",
      "description": "paid 订单实付金额合计，尚未扣退款；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "payment_cents_measure"
      }
    },
    {
      "name": "refund_cents",
      "label": "退款金额",
      "description": "paid 订单退款金额合计，按原订单下单日期归属；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "refund_cents_measure"
      }
    },
    {
      "name": "net_sales_cents",
      "label": "净销售额",
      "description": "paid 订单实付减退款后合计；取消单不计；按原订单下单日期归属；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "net_sales_cents_measure"
      }
    },
    {
      "name": "gross_cents",
      "label": "支付订单原价金额",
      "description": "paid 订单折扣前原价金额合计；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "gross_cents_measure"
      }
    },
    {
      "name": "discount_cents",
      "label": "优惠金额",
      "description": "paid 订单原价减实付的金额合计；退款不冲减原优惠金额；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "discount_cents_measure"
      }
    },
    {
      "name": "buyer_count",
      "label": "购买会员数",
      "description": "统计窗口及筛选条件内有有效订单的不同 CRM 会员账户数，不做跨系统自然人去重。",
      "type": "simple",
      "type_params": {
        "measure": "buyer_count_measure"
      }
    },
    {
      "name": "refund_buyer_count",
      "label": "退款会员数",
      "description": "统计窗口内发生退款的 paid 订单关联的不同 CRM 会员账户数。",
      "type": "simple",
      "type_params": {
        "measure": "refund_buyer_count_measure"
      }
    },
    {
      "name": "selling_store_count",
      "label": "成交门店数",
      "description": "窗口内至少有一笔有效订单的不同订单归属门店数。",
      "type": "simple",
      "type_params": {
        "measure": "selling_store_count_measure"
      }
    },
    {
      "name": "valid_order_items",
      "label": "有效订单商品件数",
      "description": "有效订单中的原始购买件数合计；退款金额不能推算退货件数，此项不是净商品销量。",
      "type": "simple",
      "type_params": {
        "measure": "valid_order_items_measure"
      }
    },
    {
      "name": "avg_order_value",
      "label": "有效订单均额",
      "description": "净销售额除以有效订单数，单位分／单；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "net_sales_cents",
        "denominator": "valid_order_count"
      }
    },
    {
      "name": "avg_buyer_value",
      "label": "购买会员人均消费",
      "description": "净销售额除以购买会员数，单位分／账户；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "net_sales_cents",
        "denominator": "buyer_count"
      }
    },
    {
      "name": "purchase_frequency",
      "label": "购买频次",
      "description": "有效订单数除以购买会员数，单位单／账户；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "valid_order_count",
        "denominator": "buyer_count"
      }
    },
    {
      "name": "refund_amount_rate",
      "label": "退款金额占比",
      "description": "退款金额除以实付金额；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "refund_cents",
        "denominator": "payment_cents"
      }
    },
    {
      "name": "cancel_rate",
      "label": "取消率",
      "description": "取消订单数除以创建订单数；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "cancelled_order_count",
        "denominator": "order_count"
      }
    },
    {
      "name": "refund_order_rate",
      "label": "退款订单率",
      "description": "退款订单数除以支付订单数；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "refund_order_count",
        "denominator": "paid_order_count"
      }
    },
    {
      "name": "discount_rate",
      "label": "优惠率",
      "description": "优惠金额除以支付订单原价金额；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "discount_cents",
        "denominator": "gross_cents"
      }
    },
    {
      "name": "items_per_order",
      "label": "单均商品件数",
      "description": "有效订单商品件数除以有效订单数；分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "valid_order_items",
        "denominator": "valid_order_count"
      }
    },
    {
      "name": "new_member_count",
      "label": "注册会员数",
      "description": "按注册日期统计新注册 CRM 账户数；不等于自然人数。",
      "type": "simple",
      "type_params": {
        "measure": "new_member_count_measure"
      }
    },
    {
      "name": "first_buyer_count",
      "label": "观测期首购会员数",
      "description": "在测试覆盖期内首次有效订单落入查询窗口的不同 CRM 账户数；先用全覆盖历史确定首次，再按窗口筛选。",
      "type": "simple",
      "type_params": {
        "measure": "first_buyer_count_measure"
      }
    },
    {
      "name": "first_order_sales_cents",
      "label": "观测期首单净销售额",
      "description": "每个账户在测试覆盖期内第一笔有效订单的净销售额，按该单日期归属；相同日期按订单号排序；单位分。",
      "type": "simple",
      "type_params": {
        "measure": "first_order_sales_cents_measure"
      }
    },
    {
      "name": "first_order_count",
      "label": "观测期首单数",
      "description": "在全测试覆盖期内先为每个账户按日期、订单号排序，其第一笔有效订单落入窗口的单数。",
      "type": "simple",
      "type_params": {
        "measure": "first_order_count_measure"
      }
    },
    {
      "name": "repeat_order_count",
      "label": "观测期后续购买订单数",
      "description": "账户全测试覆盖期内第二笔及以后的有效订单，按订单日期落入窗口计数。不是月内复购人数。",
      "type": "simple",
      "type_params": {
        "measure": "repeat_order_count_measure"
      }
    },
    {
      "name": "monthly_buyer_count",
      "label": "月内购买会员数",
      "description": "同一自然月有至少一笔有效订单的账户数，仅整月、全门店口径；不能跨月直接加总当人数。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_buyer_count_measure"
      }
    },
    {
      "name": "monthly_repeat_buyer_count",
      "label": "月内复购会员数",
      "description": "同一自然月有至少两笔有效订单的账户数，仅整月、全门店口径；不能由全量订单行上的简单条件代替。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_repeat_buyer_count_measure"
      }
    },
    {
      "name": "monthly_repeat_rate",
      "label": "月内复购率",
      "description": "同一自然月的月内复购会员数除以月内购买会员数，仅整月、全门店口径；分母零时未定义；跨多月查询必须按月展示。",
      "type": "ratio",
      "type_params": {
        "numerator": "monthly_repeat_buyer_count",
        "denominator": "monthly_buyer_count"
      }
    },
    {
      "name": "monthly_paid_buyer_count",
      "label": "月末付费会员购买人数",
      "description": "自然月内有至少一笔有效订单、且月末符合总部运营月报付费资格的不同账户数。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_paid_buyer_count_measure"
      }
    },
    {
      "name": "monthly_paid_order_count",
      "label": "月末付费会员有效订单数",
      "description": "月末符合付费资格的账户在该自然月的全部有效订单数，按账户资格筛选，不按卡重复。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_paid_order_count_measure"
      }
    },
    {
      "name": "monthly_paid_sales_cents",
      "label": "月末付费会员净销售额",
      "description": "月末符合付费资格的账户在该自然月的有效订单净销售额合计，单位分。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_paid_sales_cents_measure"
      }
    },
    {
      "name": "monthly_paid_repeat_buyer_count",
      "label": "月末付费会员复购人数",
      "description": "月末符合付费资格，且同一自然月至少有两笔有效订单的不同账户数。",
      "type": "simple",
      "type_params": {
        "measure": "monthly_paid_repeat_buyer_count_measure"
      }
    },
    {
      "name": "monthly_paid_repeat_rate",
      "label": "月末付费会员复购率",
      "description": "月末付费会员复购人数除以月末付费会员购买人数；分母为零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "monthly_paid_repeat_buyer_count",
        "denominator": "monthly_paid_buyer_count"
      }
    },
    {
      "name": "monthly_paid_avg_order_value",
      "label": "月末付费会员订单均额",
      "description": "月末付费会员净销售额除以月末付费会员有效订单数；单位分／单，分母零时未定义。",
      "type": "ratio",
      "type_params": {
        "numerator": "monthly_paid_sales_cents",
        "denominator": "monthly_paid_order_count"
      }
    }
  ],
  "catalog": [
    {
      "id": "order_count",
      "name": "创建订单数",
      "aliases": [],
      "unit": "count",
      "constraints": [],
      "sources": [
        {
          "file": "01_订单日报说明.md",
